package cl.bolsillo.app;
import android.content.Context;
import org.json.*;
final class LocalData {
 private static String preparedRevision,preparedDay,preparedData;
 interface Change {void apply(JSONObject data)throws Exception;}
 static void foldQueue(JSONObject state)throws Exception{
  JSONObject cache=state.optJSONObject("cache");JSONArray queue=state.optJSONArray("queue");if(cache==null||queue==null||queue.length()==0)return;
  JSONObject d=cache.getJSONObject("data");Finance.migrate(d);JSONArray txs=d.getJSONArray("transactions");for(int i=0;i<queue.length();i++){JSONObject e=queue.getJSONObject(i);Ledger.require(cache.optString("ownerId").equals(e.optString("ownerId")),"Hay registros de otra sesión: conserva una copia antes de migrar");JSONObject t=e.getJSONObject("tx");if(Ledger.find(txs,t.getString("id"))==null){SubscriptionRules.apply(d,t);txs.put(t);}}Ledger.validate(d);state.put("queue",new JSONArray());
 }
 static void initialize(Context c)throws Exception{synchronized(NativeStore.class){String day=Ledger.today(),revision=NativeStore.revision(c);if(preparedData!=null&&revision.equals(preparedRevision)&&day.equals(preparedDay))return;JSONObject state=NativeStore.state(c);String before=state.toString();JSONObject previous=state.optJSONObject("cache")==null?null:new JSONObject(state.getJSONObject("cache").getJSONObject("data").toString());if(state.optJSONObject("cache")==null)state.put("cache",new JSONObject().put("ownerId","local-"+Ledger.id()).put("version",1).put("data",BankCatalog.initial()));foldQueue(state);JSONObject d=state.getJSONObject("cache").getJSONObject("data");Finance.migrate(d);CategoryCatalog.migrate(d);Ledger.automatic(d);Ledger.validate(d);if(!before.equals(state.toString())){NativeStore.write(c,state);if(previous!=null)LocalAlerts.changed(c,previous,d);}preparedData=d.toString();preparedRevision=NativeStore.revision(c);preparedDay=day;}}
 static JSONObject read(Context c)throws Exception{synchronized(NativeStore.class){initialize(c);return new JSONObject(preparedData);}}
 static void change(Context c,Change change)throws Exception{synchronized(NativeStore.class){initialize(c);JSONObject s=NativeStore.state(c);JSONObject d=s.getJSONObject("cache").getJSONObject("data");JSONObject prior=new JSONObject(d.toString());java.util.Map<String,java.util.Map<String,String>> before=ChangeHistory.snapshot(d);change.apply(d);Ledger.validate(d);ChangeHistory.record(d,before);NativeStore.write(c,s);LocalAlerts.changed(c,prior,d);}BolsilloWidget.updateAll(c);}
 static void upsert(Context c,String key,JSONObject item)throws Exception{change(c,d->{if(key.equals("transactions"))SubscriptionRules.apply(d,item);JSONArray a=d.getJSONArray(key);boolean found=false;for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(item.getString("id"))){a.put(i,item);found=true;break;}if(!found)a.put(item);});}
 static void remove(Context c,String key,String id)throws Exception{change(c,d->{JSONArray a=d.getJSONArray(key);for(int i=a.length()-1;i>=0;i--)if(a.getJSONObject(i).getString("id").equals(id))a.remove(i);});}
 static boolean backedSetting(String key){return key.startsWith("cards-")||key.matches("widget-[0-9]+")||key.startsWith("quickCategory-")||java.util.Arrays.asList("sources","categoryRules","widgetAccount","widgetHidden","autoPost","paymentCards","appearance","palette","customPrimary","customSecondary","glassIntensity","quickAccount","quickKeepOpen","peopleSort","movementRules","alertChanges","alertDetections","alertVerifications","alertHideAmounts").contains(key);}
 static JSONObject backup(Context c)throws Exception{synchronized(NativeStore.class){initialize(c);JSONObject settings=new JSONObject();for(java.util.Map.Entry<String,?> entry:NativeStore.settings(c).getAll().entrySet())if(backedSetting(entry.getKey()))settings.put(entry.getKey(),entry.getValue());JSONObject state=NativeStore.state(c);return new JSONObject().put("format","bolsillo-local").put("version",1).put("settings",settings).put("exportedAt",java.time.Instant.now().toString()).put("data",read(c)).put("detectionInbox",state.optJSONArray("detectionInbox")).put("detectionEvents",state.optJSONArray("detectionEvents")).put("notificationLog",state.optJSONArray("notificationLog")).put("seen",state.optJSONArray("seen")).put("localAlertHistory",state.optJSONArray("localAlertHistory")).put("localAlertSignatures",state.optJSONObject("localAlertSignatures"));}}
 static JSONObject importData(JSONObject input)throws Exception{if(input.optString("format").equals("bolsillo-local"))Ledger.require(input.optInt("version",0)==1,"Versión de respaldo no compatible");JSONObject d=input.optJSONObject("data");if(d==null)d=input;Ledger.validate(d);return d;}
 static void restore(Context c,JSONObject input)throws Exception{
  JSONObject d=importData(input),settings=input.optJSONObject("settings");
  if(settings!=null){if(settings.has("paymentCards"))PaymentCards.validate(new JSONArray(settings.getString("paymentCards")),d.getJSONArray("accounts"));if(settings.has("sources"))Ledger.require(new JSONArray(settings.getString("sources")).length()<=100,"Demasiadas fuentes");if(settings.has("movementRules"))Ledger.require(new JSONArray(settings.getString("movementRules")).length()<=100,"Demasiadas reglas de avisos");if(settings.has("categoryRules"))Ledger.require(new JSONArray(settings.getString("categoryRules")).length()<=300,"Demasiadas reglas");}
  synchronized(NativeStore.class){JSONObject s=NativeStore.state(c);s.put("beforeImport",s.optJSONObject("cache"));String owner="local-"+Ledger.id();s.put("cache",new JSONObject().put("ownerId",owner).put("version",1).put("data",d)).put("queue",new JSONArray());for(String key:new String[]{"detectionInbox","detectionEvents","seen","notificationLog"}){JSONArray a=input.optJSONArray(key);if(a==null)a=new JSONArray();Ledger.require(a.length()<=(key.equals("detectionInbox")?500:key.equals("notificationLog")?150:1000),"Demasiadas evidencias");if(key.equals("detectionInbox")||key.equals("detectionEvents"))for(int i=0;i<a.length();i++)a.getJSONObject(i).put("ownerId",owner);s.put(key,a);}JSONArray notices=input.optJSONArray("localAlertHistory");JSONObject signatures=input.optJSONObject("localAlertSignatures");if(notices!=null){Ledger.require(notices.length()<=LocalAlerts.HISTORY_LIMIT,"Demasiados avisos en el respaldo");for(int i=0;i<notices.length();i++){JSONObject notice=notices.getJSONObject(i);Ledger.require(notice.optString("id").length()<=160&&notice.optString("body").length()<=4000,"Aviso inválido en el respaldo");}s.put("localAlertHistory",notices);}if(signatures!=null){Ledger.require(signatures.length()<=LocalAlerts.SIGNATURE_LIMIT,"Demasiadas firmas de avisos");s.put("localAlertSignatures",signatures);}NativeStore.write(c,s);
   if(settings!=null){android.content.SharedPreferences.Editor editor=NativeStore.settings(c).edit().putBoolean("capture",false);java.util.Iterator<String> keys=settings.keys();while(keys.hasNext()){String key=keys.next();if(!backedSetting(key))continue;if(java.util.Arrays.asList("autoPost","widgetHidden","quickKeepOpen","alertChanges","alertDetections","alertVerifications","alertHideAmounts").contains(key))editor.putBoolean(key,settings.optBoolean(key));else if(key.equals("customPrimary")||key.equals("customSecondary"))editor.putInt(key,0xff000000|settings.optInt(key));else if(key.equals("glassIntensity"))editor.putInt(key,Math.max(0,Math.min(2,settings.optInt(key,1))));else if(key.matches("widget-[0-9]+")){try{int widgetId=Integer.parseInt(key.substring(7));if(WidgetPreferences.belongs(c,widgetId))editor.putString(key,settings.optString(key));}catch(NumberFormatException ignored){}}else editor.putString(key,settings.optString(key));}editor.apply();}
  }BolsilloWidget.updateAll(c);
 }
}
